WITH RECURSIVE latest AS (SELECT upid,heap_name,MAX(ts) AS ts FROM heap_profile_allocation GROUP BY upid,heap_name), roots AS (SELECT a.upid,a.heap_name,a.callsite_id,SUM(a.size) AS retained_bytes FROM heap_profile_allocation a JOIN latest l USING(upid,heap_name,ts) GROUP BY a.upid,a.heap_name,a.callsite_id HAVING retained_bytes>0), chain AS (SELECT r.upid,r.heap_name,r.callsite_id AS leaf_callsite,r.retained_bytes,c.id,c.parent_id,c.frame_id,0 AS leaf_depth FROM roots r JOIN stack_profile_callsite c ON c.id=r.callsite_id UNION ALL SELECT ch.upid,ch.heap_name,ch.leaf_callsite,ch.retained_bytes,c.id,c.parent_id,c.frame_id,ch.leaf_depth+1 FROM chain ch JOIN stack_profile_callsite c ON c.id=ch.parent_id)
SELECT ch.upid,ch.heap_name,ch.leaf_callsite,ch.retained_bytes,ch.leaf_depth,f.name,f.rel_pc,m.name AS mapping_name,m.build_id FROM chain ch JOIN stack_profile_frame f ON f.id=ch.frame_id JOIN stack_profile_mapping m ON m.id=f.mapping ORDER BY ch.retained_bytes DESC,ch.leaf_callsite,ch.leaf_depth;
